-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- No tarpanam row may be invoked by a number.
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Deva Tarpanam'
     and a.invoked_name_deva ~ '^[0-9]+$';
  if n > 0 then raise exception '% tarpanam rows are still invoked by a number', n; end if;

  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Deva Tarpanam'
     and a.invoked_name_deva ~ '[\u0900-\u097F]';
  if n <> 17 then raise exception 'only % of 17 tarpanam rows have a Devanagari name', n; end if;

  -- No Latin in any nitya mantra, apart from the dynamic slot.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and replace(coalesce(mantra_sanskrit, ''), '[DYNAMIC_PANCHANGAM_DATA]', '') ~ '[A-Za-z]';
  if n > 0 then raise exception '% nitya mantras still contain Latin letters', n; end if;

  -- The sankalpam is dynamic and carries no leftover blanks.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana' and step_title_en = 'Sankalpam'
     and is_dynamic_sankalpam and mantra_sanskrit like '%[DYNAMIC_PANCHANGAM_DATA]%'
     and mantra_sanskrit not like '%*%';
  if n <> 1 then raise exception 'the nitya sankalpam is not on the dynamic frame'; end if;

  -- Samagri and naivedyam exist, with at least one primary.
  select count(*) into n from public.samagri_items where pooja_id = 'nitya_panchayatana';
  if n < 1 then raise exception 'nitya has no samagri'; end if;
  select count(*) into n from public.naivedyam_items where pooja_id = 'nitya_panchayatana' and tier = 'primary';
  if n < 1 then raise exception 'nitya has no primary naivedyam'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

